const body = $json.body ?? $json;
const activity = body.activity ?? {};
const operation = body.operation;
if (!['safety_review', 'recommend'].includes(operation)) throw new Error('unsupported operation');
if (operation === 'safety_review' && (!activity.title || !activity.purpose || !activity.description || !activity.location)) throw new Error('missing activity fields');
if (operation === 'recommend' && !Array.isArray(body.activities)) throw new Error('missing activities');
return [{ json: { requestId: String(body.requestId || crypto.randomUUID()), operation, activity, activities: body.activities || [], preferences: body.preferences || {}, normalizedText: `${activity.title || ''} ${activity.purpose || ''} ${activity.description || ''}`.normalize('NFKC').toLowerCase().replace(/[\s_\-.~!@#$%^&*()[\]{}:;,'"`/\\|]+/g, '') } }];

const input = $('검증 및 정규화').first().json;
if (input.operation === 'recommend') {
  const recommendations = Array.isArray($json.recommendations) ? $json.recommendations : [];
  return [{ json: { requestId: input.requestId, recommendations, message: recommendations.length ? '' : '조건에 맞는 활동이 없습니다.', policyVersion: $json.policyVersion || 'recommendation-v1' } }];
}
const result = $json.error ? { decision: 'manual_review', categories: [], confidence: 'low', explanation: '의미 검토 서비스를 사용할 수 없어 운영자 검토로 전환했습니다.', guidance: '잠시 후 다시 시도하거나 운영자 검토를 요청해 주세요.' } : $json;
const decision = result.decision || (result.risk === 'high' ? 'held' : result.confidence === 'low' ? 'manual_review' : 'approved');
return [{ json: { requestId: result.requestId || input.requestId, decision: ['approved', 'held', 'manual_review', 'unavailable'].includes(decision) ? decision : 'manual_review', categories: result.categories || [], confidence: result.confidence || 'low', explanation: result.explanation || '검토 결과를 확인해 주세요.', guidance: result.guidance || '내용을 수정하거나 운영자 검토를 요청해 주세요.', policyVersion: result.policyVersion || 'safety-v1' } }];
